      { x: 284, y: 142, dir: 'right' },
      { x: 268, y: 134, dir: 'right' },
    ]
    gs.camera = { x: 300 - 160, y: 150 - 112 }
    gs.PlayerRolesRuntime.rgwSpriteNum[1] = 3
    gs.PlayerRolesRuntime.rgwSpriteNum[2] = 7

