    gs.trail = [
      { x: 316, y: 142, dir: 'down' },
      { x: 332, y: 134, dir: 'down' },
    ]
    gs.camera = { x: 300 - 160, y: 150 - 112 } // sdlpal viewport = party - partyoffset

    const frames = indexedFrames(12)
    const ctx: PresentContext = {
